{
  "requirements": [
    {
      "text": "The system shall implement a multi-layer safety architecture including passive, active, and functional safety mechanisms to ensure collision protection and fail-safe operations.",
      "kaos_level": "strategic",
      "rationale": "This ensures comprehensive safety measures are in place to protect passengers and other road users."
    },
    {
      "text": "The system shall execute a Minimal Risk Maneuver within 5 seconds upon detecting critical system failures to safely pull over to a low-risk zone.",
      "kaos_level": "tactical",
      "rationale": "This ensures the vehicle can respond appropriately to failures without endangering occupants or others."
    },
    {
      "text": "The system shall continuously monitor Operational Design Domain compliance and issue a human takeover request when boundaries are approached.",
      "kaos_level": "tactical",
      "rationale": "This ensures that the vehicle operates safely within defined environments and alerts users when conditions become hazardous."
    },
    {
      "text": "The system shall minimize jerk to less than 0.5 m/s³ to ensure passenger comfort while maintaining safety during maneuvers.",
      "kaos_level": "operational",
      "rationale": "This operationalizes the smoothness requirement, balancing comfort with safety."
    },
    {
      "text": "The system shall satisfy curvature constraints ($kappa$) to prevent rollover during maneuvers at all speeds.",
      "kaos_level": "operational",
      "rationale": "Meeting these constraints is critical to maintaining vehicle stability and safety."
    },
    {
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints reliably within a response time of 100 milliseconds.",
      "kaos_level": "operational",
      "rationale": "This ensures real-time responsiveness in dynamic environments, enhancing safety and reliability."
    },
    {
      "text": "The system shall establish emergency protocols to relax smoothness constraints during critical maneuvers without compromising overall safety.",
      "kaos_level": "tactical",
      "rationale": "This allows for necessary trade-offs between safety and comfort in emergency situations."
    }
  ]
}
